declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_operate();perpus_sync_members($pdo);$operate=perpus_can_operate();$error='';$flash=perpus_flash();
if($_SERVER['REQUEST_METHOD']==='POST'&&$operate){require_valid_csrf();$anggota=(int)($_POST['anggota_id']??0);$jatuh=(string)($_POST['tanggal_jatuh_tempo']??'');$catatan=trim((string)($_POST['catatan']??''));$items=[];$exIds=$_POST['eksemplar_id']??[];if(is_array($exIds))foreach($exIds as $eid){$eid=(int)$eid;if($eid>0)$items[]=$eid;}if($anggota<=0||$jatuh===''||!$items)$error='Peminjam, jatuh tempo, dan minimal satu eksemplar buku wajib dipilih.';else{$m=perpus_member($pdo,$anggota);if(!$m||$m['status']!=='aktif')$error='Anggota tidak ditemukan atau nonaktif.';else{try{perpus_require_waktu_pembelajaran($pdo);$pdo->beginTransaction();$st=$pdo->prepare("SELECT e.id eksemplar_id,e.buku_id,e.kode_eksemplar,e.status,b.judul,b.status buku_status FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE e.id=? FOR UPDATE");$seen=[];$insert=[];foreach($items as $eid){if(isset($seen[$eid]))throw new RuntimeException('Eksemplar yang sama dipilih lebih dari satu kali.');$seen[$eid]=1;$st->execute([$eid]);$e=$st->fetch();if(!$e||$e['status']!=='tersedia'||$e['buku_status']!=='tersedia')throw new RuntimeException('Eksemplar tidak tersedia: '.($e['kode_eksemplar']??'tidak dikenal'));$insert[]=$e;}$nomor='PJ-'.date('Ymd-His').'-'.random_int(100,999);$pdo->prepare("INSERT INTO perpustakaan_peminjaman(nomor_transaksi,anggota_id,tanggal_pinjam,tanggal_jatuh_tempo,status,petugas_id,catatan) VALUES(?,?,?,?,?,?,?)")->execute([$nomor,$anggota,date('Y-m-d'),$jatuh,'dipinjam',user_id(),$catatan?:null]);$pid=(int)$pdo->lastInsertId();$dins=$pdo->prepare('INSERT INTO perpustakaan_detail_peminjaman(peminjaman_id,buku_id,eksemplar_id,jumlah,status,keterangan) VALUES(?,?,?,?,?,?)');$updE=$pdo->prepare("UPDATE perpustakaan_eksemplar SET status='dipinjam' WHERE id=?");$bookIds=[];foreach($insert as $x){$dins->execute([$pid,$x['buku_id'],$x['eksemplar_id'],1,'dipinjam',null]);$updE->execute([$x['eksemplar_id']]);$bookIds[$x['buku_id']]=$x['buku_id'];}foreach($bookIds as $bookId)perpus_sync_stock($pdo,(int)$bookId);perpus_audit_detail($pdo,'CREATE',$pid,'Membuat transaksi peminjaman '.$nomor,[],['eksemplar'=>array_map(static fn($x)=>$x['kode_eksemplar'],$insert)]);$pdo->commit();perpus_flash('Peminjaman berhasil dibuat: '.$nomor);redirect('perpustakaan/peminjaman.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Peminjaman tidak dapat disimpan.';}}}}
$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$where=[];$params=[];if($q!==''){$where[]='(p.nomor_transaksi LIKE ? OR a.kode_anggota LIKE ? OR s.nama LIKE ? OR g.nama LIKE ?)';$like="%$q%";$params=[$like,$like,$like,$like];}if(in_array($status,['dipinjam','sebagian_kembali','selesai','terlambat','dibatalkan'],true)){if($status==='terlambat'){$where[]="p.status IN ('dipinjam','sebagian_kembali') AND p.tanggal_jatuh_tempo<CURDATE()";}else{$where[]='p.status=?';$params[]=$status;}}$st=$pdo->prepare("SELECT p.*,a.kode_anggota,COALESCE(s.nama,g.nama) nama FROM perpustakaan_peminjaman p JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id".($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC');$st->execute($params);$rows=$st->fetchAll();$kelasRows=$pdo->query("SELECT mk.id,mk.nama FROM siswa_kelas sk JOIN master_kelas mk ON mk.id=sk.kelas_id JOIN tahun_pelajaran tp ON tp.id=sk.tahun_pelajaran_id WHERE sk.status='aktif' AND tp.aktif=1 GROUP BY mk.id,mk.nama ORDER BY mk.nama")->fetchAll();
$perpusWaktu=perpus_waktu_pembelajaran_aktif($pdo);$page_title='Peminjaman Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
