const soundCtl=SPLASMA_SCANNER_SOUND.bind("soundToggle");
const BASE=<?=json_encode(BASE_URL)?>,$=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function notice(t,e=false){$('loanMsg').innerHTML='<div class="alert '+(e?'alert-danger':'alert-success')+'">'+t+'</div>';setTimeout(()=>{$('loanMsg').innerHTML=''},5000)}let selectedStudent=null;
async function selectStudent(s){selectedStudent=s;if(!s.anggota_id){notice('Anggota perpustakaan belum tersedia. Silakan muat ulang halaman.','error');return}if(s.anggota_status&&s.anggota_status!=='aktif'){notice('Anggota perpustakaan untuk '+esc(s.nama)+' sedang nonaktif.','error');return}$('anggotaId').value=s.anggota_id;const ident=s.nis||s.nip||'';const jenis=s.nis?'Siswa':'Guru';$('memberBox').innerHTML='<strong>'+esc(s.nama)+'</strong><div class="text-muted small">'+esc(ident)+' · '+esc(s.kelas||'Guru')+' · Anggota '+esc(s.kode_anggota)+'</div>';$('studentSelected').innerHTML='<span class="badge bg-primary">'+jenis+' terpilih: '+esc(s.nama)+'</span>';$('studentResults').innerHTML='';notice('Anggota siap untuk peminjaman. Sekarang pilih atau scan buku.');}
async function lookupStudents(){const q=$('studentSearch').value.trim(),k=$('kelasManual').value,type=$('wargaJenis').value;if(q.length<1){$('studentResults').innerHTML='';return}let u=BASE+'perpustakaan/api.php?type='+encodeURIComponent(type)+'&q='+encodeURIComponent(q);if(type==='siswa'&&k)u+='&kelas_id='+encodeURIComponent(k);const d=await (await fetch(u,{cache:'no-store'})).json();$('studentResults').innerHTML=(d.data||[]).map(s=>'<button type="button" data-id="'+s.id+'"><strong>'+esc(s.nama)+'</strong><div class="text-muted small">'+esc(s.nis||s.nip||'')+' · '+esc(s.kelas||'Guru')+'</div></button>').join('')||'<div class="p-2 text-muted">Data tidak ditemukan.</div>';document.querySelectorAll('#studentResults button').forEach(b=>b.onclick=()=>selectStudent((d.data||[]).find(s=>String(s.id)===b.dataset.id)));}
$('wargaJenis').addEventListener('change',()=>{const guru=$('wargaJenis').value==='guru';$('kelasWrap').style.display=guru?'none':'';$('wargaLabel').textContent=guru?'3. Pilih Guru':'3. Pilih Siswa';$('studentSearch').value='';$('studentResults').innerHTML='';});
let st; $('studentSearch').addEventListener('input',()=>{clearTimeout(st);st=setTimeout(lookupStudents,180)});$('kelasManual').addEventListener('change',lookupStudents);
async function addBookByCode(code){code=(code||'').trim();if(!code)return;const d=await (await fetch(BASE+'perpustakaan/api.php?action=resolve_qr&code='+encodeURIComponent(code),{cache:'no-store'})).json();if(!d.ok){SPLASMA_SCANNER_SOUND.beep(false);notice(esc(d.message),'error');return}if(d.type==='siswa'||d.type==='guru'){SPLASMA_SCANNER_SOUND.beep(true);await selectStudent(d.data);return}if(d.type==='eksemplar'){SPLASMA_SCANNER_SOUND.beep(true);addExemplar(d.data);return}if(d.type==='buku'){SPLASMA_SCANNER_SOUND.beep(false);notice('QR master buku tidak dipakai untuk transaksi baru. Gunakan QR setiap eksemplar.','error');return}}
function addExemplar(e){if(e.status!=='tersedia'){notice('Eksemplar tidak tersedia.','error');return}if([...document.querySelectorAll('.exemplarId')].some(x=>x.value==String(e.eksemplar_id))){notice('Eksemplar '+esc(e.kode_eksemplar)+' sudah dipilih.','error');return}let row=[...document.querySelectorAll('#bookRows tr')].find(r=>!r.querySelector('.exemplarId').value);if(!row){row=document.createElement('tr');row.innerHTML=`<td><input class="form-control bookSearch" placeholder="Cari judul/kode/ISBN"><input type="hidden" name="eksemplar_id[]" class="exemplarId"><div class="search-results bookResults"></div><div class="selected-result bookSelected"></div></td><td class="condition-cell">-</td><td class="status-cell">-</td>`;document.getElementById('bookRows').appendChild(row);bindBook(row)}row.querySelector('.exemplarId').value=e.eksemplar_id;row.querySelector('.bookSearch').value=e.judul+' · '+e.kode_eksemplar;row.querySelector('.condition-cell').textContent=e.kondisi;row.querySelector('.status-cell').innerHTML='<span class=\"badge bg-success\">Tersedia</span>';row.querySelector('.bookResults').innerHTML='';notice('Eksemplar ditambahkan: '+esc(e.kode_eksemplar));}
function bindBook(row){const q=row.querySelector('.bookSearch'),id=row.querySelector('.exemplarId'),box=row.querySelector('.bookResults'),sel=row.querySelector('.bookSelected'),cell=row.querySelector('.condition-cell'),status=row.querySelector('.status-cell');let t;q.addEventListener('input',()=>{clearTimeout(t);const v=q.value.trim();if(v.length<1){box.innerHTML='';return}t=setTimeout(async()=>{const d=await (await fetch(BASE+'perpustakaan/api.php?type=buku&q='+encodeURIComponent(v),{cache:'no-store'})).json();box.innerHTML=(d.data||[]).map(b=>'<button type=\"button\" data-id=\"'+b.id+'\"><strong>'+esc(b.judul)+'</strong> · '+Number(b.tersedia||0)+' tersedia</button>').join('')||'<div class=\"p-2 text-muted\">Buku tidak ditemukan.</div>';box.querySelectorAll('button').forEach(btn=>btn.onclick=async()=>{const r=await (await fetch(BASE+'perpustakaan/api.php?type=eksemplar&buku_id='+btn.dataset.id,{cache:'no-store'})).json();const e=(r.data||[])[0];if(!e){notice('Tidak ada eksemplar tersedia.','error');return}addExemplar(e)})},180)});}bindBook(document.querySelector('#bookRows tr'));$('addBook').onclick=()=>{const tr=document.createElement('tr');tr.innerHTML=`<td><input class="form-control bookSearch" placeholder="Cari judul/kode/ISBN"><input type="hidden" name="eksemplar_id[]" class="exemplarId"><div class="search-results bookResults"></div><div class="selected-result bookSelected"></div></td><td class="condition-cell">-</td><td class="status-cell">-</td>`;document.getElementById('bookRows').appendChild(tr);bindBook(tr)};
PerpusScanner.bindUsb('usb',addBookByCode);$('detectCamera').onclick=()=>PerpusScanner.detect();$('startCamera').onclick=()=>PerpusScanner.start(addBookByCode);$('stopCamera').onclick=()=>PerpusScanner.stop();(navigator.serviceWorker?.ready?navigator.serviceWorker.ready:Promise.resolve()).then(()=>PerpusScanner.loadDecoder()).catch(()=>PerpusScanner.loadDecoder());PerpusScanner.detect();
</script><?php require_once __DIR__.'/../layouts/footer.php';
